import unittest
from candidate import mean_absolute_deviation

class TestMeanAbsoluteDeviation(unittest.TestCase):
    def test_mad_normal_case(self):
        self.assertAlmostEqual(mean_absolute_deviation([1.0, 2.0, 3.0, 4.0]), 1.0)

    def test_mad_single_element(self):
        self.assertAlmostEqual(mean_absolute_deviation([5.0]), 0.0)

    def test_mad_all_same(self):
        self.assertAlmostEqual(mean_absolute_deviation([3.0, 3.0, 3.0]), 0.0)

    def test_mad_negative_numbers(self):
        self.assertAlmostEqual(mean_absolute_deviation([-2, -1, 0, 1, 2]), 1.2)

    def test_mad_mixed_integers_and_floats(self):
        result = mean_absolute_deviation([1.5, 2, 3.5])
        self.assertAlmostEqual(result, 0.7777777777777777)

    def test_mad_large_numbers(self):
        result = mean_absolute_deviation([1e12, 1e12 + 1, 1e12 - 1])
        self.assertAlmostEqual(result, 0.6666666666666666)

    def test_mad_tuple_input(self):
        self.assertAlmostEqual(mean_absolute_deviation((1, 2, 3, 4)), 1.0)

    def test_mad_generator_input(self):
        gen = (x for x in [1, 2, 3, 4])
        self.assertAlmostEqual(mean_absolute_deviation(gen), 1.0)

    def test_mad_set_input(self):
        self.assertAlmostEqual(mean_absolute_deviation({1, 2, 3, 4}), 1.0)

    def test_mad_empty_list_raises(self):
        with self.assertRaises(ZeroDivisionError):
            mean_absolute_deviation([])

    def test_mad_none_input_raises(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation(None)

    def test_mad_invalid_element_type_raises(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation([1, '2', 3])

    def test_mad_none_element_in_list_raises(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation([1, None, 3])

    def test_mad_non_iterable_input_raises(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation(5)

    def test_mad_float_precision(self):
        result = mean_absolute_deviation([0.1, 0.2, 0.3])
        self.assertAlmostEqual(result, 0.06666666666666667)

    def test_mad_boolean_elements(self):
        result = mean_absolute_deviation([True, False, True])
        self.assertAlmostEqual(result, 0.4444444444444444)

    def test_mad_returns_float_type(self):
        result = mean_absolute_deviation([1, 2, 3])
        self.assertIsInstance(result, float)

    def test_mad_deterministic(self):
        values = [1, 2, 3, 4]
        first = mean_absolute_deviation(values)
        second = mean_absolute_deviation(values)
        self.assertAlmostEqual(first, second)

if __name__ == '__main__':
    unittest.main()
